window.ENGO_G8_LISTENING_SETS = {"unit1":{"unit":1,"title":"Leisure Time","levels":[{"level":"easy","title":"Leisure Activities and Hobbies","intro":"Hãy nghe 5 câu ngắn sau đây về các hoạt động trong thời gian rảnh rỗi và trả lời câu hỏi.","script":["My brother is crazy about playing computer games.","We often go cycling around the lake on Sundays.","She saved money to buy a new camera.","Making paper flowers helps me increase my creativity.","They detest spending all day watching online videos."],"questions":[{"prompt":"What activity is the speaker's brother crazy about?","options":["A. Playing computer games","B. Reading books","C. Riding a horse","D. Cooking pumpkin soup"],"answer":0,"explanation":"Căn cứ vào câu nghe được: \"My brother is crazy about playing computer games.\""},{"prompt":"Where do they often go cycling on Sundays?","options":["A. In the park","B. Around the lake","C. On the hill","D. Near the museum"],"answer":1,"explanation":"Căn cứ vào câu nghe được: \"We often go cycling around the lake on Sundays.\""},{"prompt":"Why did she save money?","options":["A. To buy a knitting kit","B. To buy a new phone","C. To buy a new camera","D. To go to the cinema"],"answer":2,"explanation":"Căn cứ vào câu nghe được: \"She saved money to buy a new camera.\""},{"prompt":"What activity helps the speaker increase creativity?","options":["A. Doing puzzles","B. Surfing the net","C. Making paper flowers","D. Building dollhouses"],"answer":2,"explanation":"Căn cứ vào câu nghe được: \"Making paper flowers helps me increase my creativity.\""}]},{"level":"medium","title":"Planning Weekend Leisure Activities","intro":"Lắng nghe cuộc hội thoại gồm 8 lượt lời giữa Nick và Hoa về các hoạt động cuối tuần.","script":["A: Hi Hoa, do you have any plans for this Saturday afternoon?","B: I am thinking of staying at home to do some DIY activities.","A: That sounds interesting! Are you going to build dollhouses again?","B: No, I want to try making pumpkin soup for my family.","A: Wow, I didn't know you were interested in cooking!","B: Yes, learning to cook helps me relax and gain new life skills.","A: Would you like to go cycling with me on Sunday morning instead?","B: I would love to! Riding a bike is great for physical health."],"questions":[{"prompt":"When is Hoa planning to do DIY activities?","options":["A. Saturday morning","B. Saturday afternoon","C. Sunday morning","D. Sunday afternoon"],"answer":1,"explanation":"Nick hỏi về \"Saturday afternoon\" và Hoa đáp \"I am thinking of staying at home to do some DIY activities.\""},{"prompt":"What DIY activity is Hoa planning to do this Saturday?","options":["A. Building dollhouses","B. Making paper flowers","C. Cooking pumpkin soup","D. Knitting a scarf"],"answer":2,"explanation":"Hoa trả lời: \"No, I want to try making pumpkin soup for my family.\""},{"prompt":"Why does Hoa like learning to cook?","options":["A. To save money and buy clothes","B. To relax and gain new life skills","C. To improve computer skills","D. To make new friends at school"],"answer":1,"explanation":"Hoa giải thích: \"learning to cook helps me relax and gain new life skills.\""},{"prompt":"What does Nick invite Hoa to do on Sunday morning?","options":["A. Go cycling","B. Go to the cinema","C. Surf the net","D. Go to the museum"],"answer":0,"explanation":"Nick mời: \"Would you like to go cycling with me on Sunday morning instead?\""},{"prompt":"What benefit of riding a bike does Hoa mention?","options":["A. Improving mental exercise","B. Great for physical health","C. Saving money","D. Developing creativity"],"answer":1,"explanation":"Hoa khẳng định: \"Riding a bike is great for physical health.\""}]},{"level":"hard","title":"A Presentation on Teen Leisure Time","intro":"Nghe đoạn bài nói về thói quen sinh hoạt và thời gian rảnh rỗi của giới trẻ hiện nay.","script":["Nowadays, teenagers have various options to spend their leisure time, ranging from indoor hobbies to outdoor sports.","While many students are crazy about surfing the net and messaging friends on social networks, others prefer active choices like going cycling or playing sports to improve their physical health.","Furthermore, creative activities such as building dollhouses, making paper flowers, or doing DIY projects are becoming popular because they encourage creativity and reduce daily stress.","According to recent surveys, finding a balance between digital entertainment and physical exercise is essential for young people to maintain good mental health and develop social skills.","Therefore, parents should encourage their children to join outdoor clubs, visit museum exhibits, and make new friends in real life."],"questions":[{"prompt":"What are many students crazy about doing on social networks?","options":["A. Building dollhouses and crafting","B. Surfing the net and messaging friends","C. Cooking pumpkin soup","D. Riding horses in the countryside"],"answer":1,"explanation":"Bài nói nêu: \"many students are crazy about surfing the net and messaging friends on social networks\"."},{"prompt":"Why do some teenagers prefer active choices like cycling or playing sports?","options":["A. To improve their physical health","B. To save money","C. To practice computer skills","D. To pass school exams"],"answer":0,"explanation":"Bài nói ghi rõ: \"others prefer active choices like going cycling or playing sports to improve their physical health.\""},{"prompt":"Why are creative DIY activities becoming popular among teenagers?","options":["A. Because they cost no money at all","B. Because they are required by school teachers","C. Because they encourage creativity and reduce daily stress","D. Because they help teens master computer skills"],"answer":2,"explanation":"Đoạn văn nêu rõ: \"because they encourage creativity and reduce daily stress.\""},{"prompt":"What is essential for young people according to recent surveys?","options":["A. Spending all free time on digital devices","B. Avoiding all physical exercise","C. Finding a balance between digital entertainment and physical exercise","D. Watching comedies every evening"],"answer":2,"explanation":"Bài nghe ghi nhận: \"finding a balance between digital entertainment and physical exercise is essential for young people\"."},{"prompt":"What does the speaker suggest parents should encourage their children to do?","options":["A. Stay at home and surf the net all day","B. Avoid making friends in real life","C. Join outdoor clubs, visit museum exhibits, and make new friends","D. Stop doing DIY projects completely"],"answer":2,"explanation":"Đoạn cuối kết luận: \"parents should encourage their children to join outdoor clubs, visit museum exhibits, and make new friends in real life.\""}]}]},"unit2":{"unit":2,"title":"Life in the Countryside","levels":[{"level":"easy","title":"Life in a Peaceful Village","intro":"Hãy nghe 5 câu độc lập về cuộc sống ở nông thôn và chọn câu trả lời đúng cho từng câu hỏi.","script":["Farmers use a combine harvester to collect rice fast.","My aunt feeds her poultry early every morning.","The vast paddy fields look golden in autumn.","Local people are very hospitable to every visitor.","Children love playing traditional games in the village."],"questions":[{"prompt":"What machine do farmers use to collect rice fast?","options":["A. A combine harvester","B. A modern truck","C. A water pump","D. An electric plough"],"answer":0,"explanation":"Trích câu 1: 'Farmers use a combine harvester to collect rice fast.'"},{"prompt":"What does the aunt feed early every morning?","options":["A. Her cattle","B. Her poultry","C. Her pigs","D. Her dogs"],"answer":1,"explanation":"Trích câu 2: 'My aunt feeds her poultry early every morning.'"},{"prompt":"How do the vast paddy fields look in autumn?","options":["A. Green","B. Golden","C. Brown","D. Yellow"],"answer":1,"explanation":"Trích câu 3: 'The vast paddy fields look golden in autumn.'"},{"prompt":"How are the local people towards visitors?","options":["A. Busy","B. Quiet","C. Hospitable","D. Hard-working"],"answer":2,"explanation":"Trích câu 4: 'Local people are very hospitable to every visitor.'"}]},{"level":"medium","title":"A Visit to the Countryside","intro":"Lắng nghe đoạn hội thoại giữa Minh và Mai về chuyến thăm quê nhà và trả lời câu hỏi.","script":["A: Hi Mai, did you return to your hometown last weekend?","B: Yes, Minh! I visited my grandparents in the countryside.","A: What did you do there during your stay?","B: I helped my uncle unload fresh vegetables from his truck.","A: Did you also feed the pigs or milk cows?","B: I fed the pigs and collected fresh eggs from poultry.","A: Wow, that sounds like a busy but fun day!","B: Yes, the villagers were so friendly and hardworking."],"questions":[{"prompt":"When did Mai visit her hometown?","options":["A. Last weekend","B. Last month","C. Yesterday morning","D. Two weeks ago"],"answer":0,"explanation":"Minh hỏi: 'did you return to your hometown last weekend?' và Mai xác nhận 'Yes'."},{"prompt":"Who did Mai visit in the countryside?","options":["A. Her aunt","B. Her teacher","C. Her grandparents","D. Her friends"],"answer":2,"explanation":"Mai nói: 'I visited my grandparents in the countryside.'"},{"prompt":"What did Mai help her uncle do?","options":["A. Plough the fields","B. Unload fresh vegetables from his truck","C. Herd cattle in the field","D. Load rice onto trucks"],"answer":1,"explanation":"Mai nói: 'I helped my uncle unload fresh vegetables from his truck.'"},{"prompt":"Which farm activity did Mai perform?","options":["A. Milk cows","B. Feed the pigs","C. Drive a tractor","D. Catch fish"],"answer":1,"explanation":"Mai trả lời: 'I fed the pigs and collected fresh eggs from poultry.'"},{"prompt":"How does Mai describe the villagers?","options":["A. Quiet and shy","B. Friendly and hardworking","C. Hospitable and rich","D. Polite and clever"],"answer":1,"explanation":"Mai nhận xét: 'the villagers were so friendly and hardworking.'"}]},{"level":"hard","title":"Harvest Time in a Picturesque Village","intro":"Hãy nghe bài nói về mùa thu hoạch tại một vùng quê thanh bình và trả lời các câu hỏi sau.","script":["Harvest season is always the busiest yet most exciting time of the year in my home village.","As the vast golden paddy fields stretch across the valley, local farmers start using modern combine harvesters to gather their crops quickly while well-trained workers load heavy rice bags onto trucks.","In the afternoon, young children happily play dragon-snake in the village yard while adults dry the rice grains in the bright sunshine and feed their cattle.","Surrounded by picturesque green hills, the entire countryside offers visitors an enjoyable and peaceful atmosphere far away from crowded city life.","Everyone visiting this lovely province is deeply impressed by the warm hospitality of the hard-working local people."],"questions":[{"prompt":"What makes harvest season special in the village?","options":["A. It is the quietest time of the year","B. It is the busiest yet most exciting time","C. Farmers stop working in the fields","D. Visitors leave the village early"],"answer":1,"explanation":"Bài nghe nêu: 'Harvest season is always the busiest yet most exciting time of the year in my home village.'"},{"prompt":"What do farmers use to gather their crops quickly?","options":["A. Traditional wooden ploughs","B. Modern combine harvesters","C. Small hand sickles","D. Large cargo boats"],"answer":1,"explanation":"Bài nghe nêu: 'local farmers start using modern combine harvesters to gather their crops quickly...'"},{"prompt":"What game do young children play in the afternoon?","options":["A. Hide and seek","B. Blind man's buff","C. Dragon-snake","D. Tug of war"],"answer":2,"explanation":"Bài nghe nêu: 'young children happily play dragon-snake in the village yard...'"},{"prompt":"What surrounds the countryside mentioned in the passage?","options":["A. Tall city skyscrapers","B. Picturesque green hills","C. Deep blue ocean waters","D. Large industrial factories"],"answer":1,"explanation":"Bài nghe nêu: 'Surrounded by picturesque green hills...'"},{"prompt":"What impresses visitors when they come to this province?","options":["A. The cheap cost of living","B. The warm hospitality of local people","C. The noisy nightlife","D. The modern transportation system"],"answer":1,"explanation":"Bài nghe nêu: 'Everyone visiting this lovely province is deeply impressed by the warm hospitality of the hard-working local people.'"}]}]},"unit3":{"unit":3,"title":"Teenagers","levels":[{"level":"easy","title":"Listening Practice: Teenagers Daily Life","intro":"Nghe các câu ngắn và chọn đáp án đúng nhất.","script":["Teenagers often feel stressed before midterm exams.","She joins the school craft club every Tuesday.","Please log on to the forum to discuss the project.","We need to stay calm under academic pressure.","The website is very user-friendly for young students."],"questions":[{"prompt":"How do teenagers often feel before midterm exams?","options":["A. Happy","B. Stressed","C. Excited","D. Relaxed"],"answer":1,"explanation":"Nghe được: Teenagers often feel stressed before midterm exams."},{"prompt":"When does she join the school craft club?","options":["A. Every Monday","B. Every Tuesday","C. Every Wednesday","D. Every Thursday"],"answer":1,"explanation":"Nghe được: She joins the school craft club every Tuesday."},{"prompt":"Where should students log on to discuss the project?","options":["A. The forum","B. The game store","C. The library","D. The canteen"],"answer":0,"explanation":"Nghe được: Please log on to the forum to discuss the project."},{"prompt":"What do students need to do under academic pressure?","options":["A. Shout loudly","B. Give up","C. Stay calm","D. Sleep more"],"answer":2,"explanation":"Nghe được: We need to stay calm under academic pressure."},{"prompt":"How is the website described for young students?","options":["A. Difficult","B. Boring","C. User-friendly","D. Expensive"],"answer":2,"explanation":"Nghe được: The website is very user-friendly for young students."}]},{"level":"medium","title":"Listening Practice: School Clubs and Competitions","intro":"Nghe đoạn hội thoại giữa hai học sinh và trả lời câu hỏi.","script":["A: Hi Mark, are you joining the school chess tournament this weekend?","B: Yes, Mai. I am very excited, but I also feel a bit pressured.","A: Why do you feel pressured? You are a great player.","B: Because there are many strong competitors from other classes.","A: Just concentrate on your moves and stay calm.","B: Thanks, Mai. I will upload my game results to our club forum later.","A: That sounds great. Good luck with your match!","B: Thank you very much for your advice."],"questions":[{"prompt":"What event is Mark joining this weekend?","options":["A. A craft competition","B. A chess tournament","C. A swimming race","D. An English contest"],"answer":1,"explanation":"Mark tham gia giải đấu cờ vua (chess tournament)."},{"prompt":"Why does Mark feel a bit pressured?","options":["A. There are many strong competitors","B. He does not like chess","C. He has no time","D. The rules are difficult"],"answer":0,"explanation":"Mark cảm thấy áp lực vì có nhiều đối thủ mạnh (strong competitors)."},{"prompt":"What does Mai advise Mark to do?","options":["A. Stop playing","B. Concentrate and stay calm","C. Ask the teacher","D. Change his hobby"],"answer":1,"explanation":"Mai khuyên Mark tập trung và bình tĩnh (concentrate on your moves and stay calm)."},{"prompt":"Where will Mark upload his game results?","options":["A. On Facebook","B. On his personal blog","C. To their club forum","D. To the school notice board"],"answer":2,"explanation":"Mark sẽ tải kết quả lên diễn đàn câu lạc bộ (club forum)."},{"prompt":"How does Mark feel after talking with Mai?","options":["A. More confident and thankful","B. Angry and worried","C. Confused","D. Tired"],"answer":0,"explanation":"Mark cảm ơn Mai vì lời khuyên và cảm thấy thoải mái hơn."}]},{"level":"hard","title":"Listening Practice: Teenage Stress and Online Safety","intro":"Nghe đoạn thông tin dài về các vấn đề của tuổi thiếu niên và chọn đáp án chính xác.","script":["Being a teenager in modern society can sometimes be very stressful. Students face heavy expectations from parents and teachers regarding their midterm exam results. This academic pressure often leads to high levels of stress, making it hard for teenagers to concentrate on their studies. To cope with this, many students turn to school clubs, such as craft or chess clubs, where they can relax and connect with peers who share similar interests. Additionally, online forums provide a space for teenagers to discuss their problems and support one another. However, users must be careful with cyberbullying. If someone receives scary messages or notices online harassment, they should immediately block the bully and notify adults to ensure a safe digital environment."],"questions":[{"prompt":"What is one main cause of stress for teenagers mentioned in the talk?","options":["A. Heavy expectations regarding midterm exams","B. Lack of pocket money","C. Boring school uniforms","D. Too many outdoor sports"],"answer":0,"explanation":"Kỳ vọng nặng nề về kết quả thi giữa kỳ gây ra căng thẳng."},{"prompt":"What effect does high stress have on students?","options":["A. It helps them sleep better","B. It makes it hard to concentrate","C. It improves their memory","D. It makes them more creative"],"answer":1,"explanation":"Căng thẳng cao khiến học sinh khó tập trung vào việc học."},{"prompt":"Where do students go to relax and share interests?","options":["A. Part-time jobs","B. School clubs like craft or chess","C. Shopping malls","D. Extra math classes"],"answer":1,"explanation":"Học sinh tham gia các câu lạc bộ như thủ công hoặc cờ vua để thư giãn."},{"prompt":"What is a potential danger on online forums?","options":["A. Slow internet connection","B. Cyberbullying","C. Expensive subscription fees","D. Too many advertisements"],"answer":1,"explanation":"Bắt nạt trên mạng (cyberbullying) là một mối nguy hiểm tiềm ẩn."},{"prompt":"What should students do if they face online harassment?","options":["A. Ignore it and delete their account","B. Send scary messages back","C. Block the bully and notify adults","D. Quit school immediately"],"answer":2,"explanation":"Học sinh nên chặn kẻ bắt nạt và thông báo cho người lớn."}]}]},"unit4":{"unit":4,"title":"Ethnic Groups of Viet Nam","levels":[{"level":"easy","title":"Listening Practice - Easy Level","intro":"Nghe các câu ngắn và chọn đáp án đúng về đời sống các dân tộc.","script":["The ethnic minority groups live mainly in the highland region.","Stilt houses are made from natural wood and bamboo.","Villagers wear colourful traditional costumes during the festival.","The gong is a very important musical instrument in the Central Highlands.","People plant rice on terraced fields to get a good harvest."],"questions":[{"prompt":"Where do ethnic minority groups mainly live?","options":["A. In the lowland region","B. In the highland region","C. In big modern cities","D. Near the big beaches"],"answer":1,"explanation":"Nghe được: 'The ethnic minority groups live mainly in the highland region.'"},{"prompt":"What are stilt houses made from?","options":["A. Natural wood and bamboo","B. Steel and modern glass","C. Plastic and concrete","D. Bricks and iron"],"answer":0,"explanation":"Nghe được: 'Stilt houses are made from natural wood and bamboo.'"},{"prompt":"When do villagers wear colourful traditional costumes?","options":["A. During normal working days","B. During the festival","C. When cleaning the house","D. When going to bed"],"answer":1,"explanation":"Nghe được: 'Villagers wear colourful traditional costumes during the festival.'"},{"prompt":"Which instrument is very important in the Central Highlands?","options":["A. The piano","B. The guitar","C. The gong","D. The violin"],"answer":2,"explanation":"Nghe được: 'The gong is a very important musical instrument in the Central Highlands.'"}]},{"level":"medium","title":"Listening Practice - Medium Level","intro":"Nghe đoạn hội thoại giữa hai bạn học sinh về phong tục tập quán các dân tộc.","script":["A: Hello Nam, are you reading a book about Vietnamese ethnic groups?","B: Yes, Lan. I am learning about the culture of the minority people in the highlands.","A: Do they live in stilt houses?","B: That is right. Their houses usually stand on tall wooden posts.","A: Is there a big house for community meetings in the village?","B: Yes, it is called the communal house, or nha rong.","A: What do they do for a living?","B: They grow rice on terraced fields and raise livestock like cattle."],"questions":[{"prompt":"What is Nam reading a book about?","options":["A. Vietnamese ethnic groups","B. Modern city life","C. Foreign geography","D. Wild animals"],"answer":0,"explanation":"Nam đang đọc sách về các dân tộc thiểu số Việt Nam."},{"prompt":"What do houses of highland people usually stand on?","options":["A. High stone walls","B. Tall wooden posts","C. Floating boats","D. Deep holes"],"answer":1,"explanation":"Nhà của họ thường đứng trên các cột gỗ cao."},{"prompt":"What is the big house for community meetings called?","options":["A. Pagoda","B. Temple","C. Communal house","D. Boarding school"],"answer":2,"explanation":"Ngôi nhà dùng cho họp mặt cộng đồng gọi là nhà rông (communal house)."},{"prompt":"How do they grow rice in the highlands?","options":["A. On flat sandy beaches","B. On terraced fields","C. In indoor greenhouses","D. On water surfaces"],"answer":1,"explanation":"Họ trồng lúa trên ruộng bậc thang (terraced fields)."},{"prompt":"What kind of livestock do they raise?","options":["A. Cattle","B. Sharks","C. Lions","D. Penguins"],"answer":0,"explanation":"Họ chăn nuôi gia súc như gia súc lớn (cattle)."}]},{"level":"hard","title":"Listening Practice - Hard Level","intro":"Nghe bài nói chuyện dài về sự phong phú trong văn hóa các dân tộc Việt Nam.","script":["Viet Nam is a multi-ethnic country with fifty-four distinct ethnic groups, each having its own rich culture and traditions. The Kinh group accounts for the majority of the population, while the other fifty-three groups are ethnic minorities living mostly in highland and mountainous areas. Ethnologists often visit these remote regions to study local customs, weaving techniques, and unique agricultural practices like farming on terraced fields.","Life in these communities is closely connected with nature. People build stilt houses from wood and bamboo to protect themselves from wild animals and floods. During special festivals, traditional culture comes alive as villagers play musical instruments like flutes and gongs, dance around the open fire, and wear colourful hand-woven costumes. These valuable cultural features enrich the overall heritage of Viet Nam and attract many tourists from around the world."],"questions":[{"prompt":"How many distinct ethnic groups are there in Viet Nam?","options":["A. Forty-five groups","B. Fifty-four groups","C. Sixty-three groups","D. Fifty-three groups"],"answer":1,"explanation":"Việt Nam có 54 dân tộc khác nhau."},{"prompt":"Where do most ethnic minorities live?","options":["A. In big coastal cities","B. In highland and mountainous areas","C. In the lowland delta","D. On small islands"],"answer":1,"explanation":"Đa số các dân tộc thiểu số sống ở vùng cao và miền núi."},{"prompt":"Why do people build stilt houses from wood and bamboo?","options":["A. To show wealth to neighbors","B. To protect against wild animals and floods","C. To follow modern architectural trends","D. To make the house easily movable"],"answer":1,"explanation":"Nhà sàn được làm từ gỗ và tre để bảo vệ khỏi động vật hoang dã và lũ lụt."},{"prompt":"What activities happen during special festivals?","options":["A. Playing musical instruments and dancing","B. Working hard on rice fields","C. Studying foreign languages","D. Building new stilt houses"],"answer":0,"explanation":"Trong lễ hội, mọi người chơi nhạc cụ, múa quanh lửa hồng và mặc trang phục rực rỡ."},{"prompt":"What do these diverse cultural features do for Viet Nam?","options":["A. They make the country poorer.","B. They enrich the overall heritage.","C. They create traffic problems.","D. They reduce tourism."],"answer":1,"explanation":"Các đặc điểm văn hóa này làm giàu thêm di sản chung của Việt Nam."}]}]},"unit5":{"unit":5,"title":"Our Customs and Traditions","levels":[{"level":"easy","title":"Understanding Vietnamese Customs","intro":"Nghe các câu ngắn và chọn đáp án đúng về phong tục tập quán.","script":["Family reunion is very important during the Lunar New Year.","People often eat young rice during the autumn festival.","Children admire elders who keep traditional values alive.","Bad spirits are chased away by loud lion dances.","Table manners show respect during family meals."],"questions":[{"prompt":"What is very important during the Lunar New Year?","options":["A. Family reunion","B. School contest","C. Coastal tour","D. Hard work"],"answer":0,"explanation":"Nghe được: 'Family reunion is very important during the Lunar New Year.'"},{"prompt":"What do people often eat during the autumn festival?","options":["A. Spring roll","B. Young rice","C. Carp fish","D. Sticky cake"],"answer":1,"explanation":"Nghe được: 'People often eat young rice during the autumn festival.'"},{"prompt":"Who do children admire?","options":["A. Contestants","B. Decorators","C. Elders who keep traditional values alive","D. Festival goers"],"answer":2,"explanation":"Nghe được: 'Children admire elders who keep traditional values alive.'"},{"prompt":"How are bad spirits chased away?","options":["A. Loud lion dances","B. Quiet prayers","C. Flower decoration","D. Boat racing"],"answer":0,"explanation":"Nghe được: 'Bad spirits are chased away by loud lion dances.'"}]},{"level":"medium","title":"Discussing Traditional Festivals","intro":"Nghe đoạn hội thoại giữa hai bạn học sinh về các lễ hội truyền thống.","script":["A: Hi Phong, do you know why people plant a bamboo pole during Tet?","B: Yes, Mai. Tradition says it helps chase away bad spirits from the house.","A: That is very interesting. What about the carp fish?","B: People use carp as an offering to transport Kitchen Gods to heaven.","A: I see. Are there any contests during the village festival?","B: Sure, there is a cooking contest and martial arts performance.","A: Wow, I would love to be a contestant next year.","B: You should! It is a wonderful celebration of our culture."],"questions":[{"prompt":"Why do people plant a bamboo pole during Tet according to tradition?","options":["A. To decorate the garden","B. To chase away bad spirits","C. To hang lanterns","D. To welcome guests"],"answer":1,"explanation":"Phong trả lời: 'Tradition says it helps chase away bad spirits from the house.'"},{"prompt":"What is the carp fish used for?","options":["A. An offering for Kitchen Gods","B. A decoration for the altar","C. A meal for family reunion","D. A gift for monks"],"answer":0,"explanation":"Phong nói: 'People use carp as an offering to transport Kitchen Gods to heaven.'"},{"prompt":"What activities happen during the village festival?","options":["A. Swimming and running","B. Singing and dancing","C. Cooking contest and martial arts performance","D. Flower arrangement and painting"],"answer":2,"explanation":"Phong nhắc đến: 'there is a cooking contest and martial arts performance.'"},{"prompt":"What does Mai want to be next year?","options":["A. A decorator","B. A contestant","C. A monk","D. A festival goer"],"answer":1,"explanation":"Mai nói: 'I would love to be a contestant next year.'"},{"prompt":"How do they describe the festival?","options":["A. A wonderful celebration of our culture","B. A boring local custom","C. A modern sporting event","D. A quiet family gathering"],"answer":0,"explanation":"Phong kết luận: 'It is a wonderful celebration of our culture.'"}]},{"level":"hard","title":"Preserving Cultural Heritage and Customs","intro":"Nghe bài nói dài về tầm quan trọng của việc bảo tồn di sản văn hóa và phong tục.","script":"Customs and traditions play an essential role in shaping the identity of any nation. In Viet Nam, passed-down practices like ancestor worship and celebrating Tet help maintain strong family bonding and social unity. When families gather to prepare traditional dishes and clean their homes, younger generations learn to respect their roots. Furthermore, local authorities often hold cultural events, such as boat racing and folk singing contests, which attract many enthusiastic festival goers. Although modern life brings rapid changes, preserving these admirable traditions ensures that our cultural heritage remains alive and valued for future generations to come.","questions":[{"prompt":"What role do customs and traditions play according to the talk?","options":["A. They shape the identity of a nation","B. They create economic wealth","C. They replace modern technology","D. They slow down social progress"],"answer":0,"explanation":"Câu đầu tiên: 'Customs and traditions play an essential role in shaping the identity of any nation.'"},{"prompt":"What do ancestor worship and Tet celebrations help maintain?","options":["A. Financial stability","B. Strong family bonding and social unity","C. Foreign tourism","D. Agricultural growth"],"answer":1,"explanation":"Bài nói nêu: 'help maintain strong family bonding and social unity.'"},{"prompt":"What do younger generations learn when families gather?","options":["A. How to cook foreign food","B. To respect their roots","C. How to win contests","D. To speak other languages"],"answer":1,"explanation":"Bài nói chỉ ra: 'younger generations learn to respect their roots.'"},{"prompt":"What events do local authorities often hold?","options":["A. Boat racing and folk singing contests","B. Science fairs and math competitions","C. Fashion shows and art exhibitions","D. Business meetings and workshops"],"answer":0,"explanation":"Bài nói nhắc đến: 'cultural events, such as boat racing and folk singing contests'"},{"prompt":"Why is preserving admirable traditions important?","options":["A. To increase local taxes","B. To attract foreign investment","C. To ensure cultural heritage remains alive and valued","D. To stop people from traveling"],"answer":2,"explanation":"Câu cuối cùng: 'ensures that our cultural heritage remains alive and valued for future generations to come.'"}]}]},"unit6":{"unit":6,"title":"Lifestyles","levels":[{"level":"easy","title":"Basic Lifestyle Habits","intro":"Nghe các câu ngắn về thói quen sinh hoạt và chọn đáp án đúng.","script":["People in nomadic tribes move frequently.","She likes making traditional crafts at home.","Online learning helps students study independently.","Street food is a staple part of local culture.","Waiters serve delicious food to customers."],"questions":[{"prompt":"What do people in nomadic tribes do?","options":["A. Move frequently","B. Build big skyscrapers","C. Work in offices","D. Stay in one place"],"answer":0,"explanation":"Nghe được: 'People in nomadic tribes move frequently.'"},{"prompt":"What does she like doing at home?","options":["A. Making traditional crafts","B. Playing computer games","C. Watching online learning","D. Cooking street food"],"answer":0,"explanation":"Nghe được: 'She likes making traditional crafts at home.'"},{"prompt":"How does online learning help students?","options":["A. Study independently","B. Rely on others","C. Sleep longer","D. Travel abroad"],"answer":0,"explanation":"Nghe được: 'Online learning helps students study independently.'"},{"prompt":"What is described as a staple part of local culture?","options":["A. Street food","B. Modern technology","C. Office work","D. Heavy traffic"],"answer":0,"explanation":"Nghe được: 'Street food is a staple part of local culture.'"},{"prompt":"What do waiters do?","options":["A. Serve delicious food to customers","B. Drive dogsleds","C. Build igloos","D. Teach online classes"],"answer":0,"explanation":"Nghe được: 'Waiters serve delicious food to customers.'"}]},{"level":"medium","title":"Greetings and Interactions","intro":"Nghe đoạn hội thoại ngắn về cách chào hỏi và tương tác xã hội.","script":["A: Hi Mark, do people in your country shake hands when they meet?","B: Yes, we normally shake hands, and close friends might hug.","A: What about bowing? Do you bow like people in Japan?","B: No, we don't bow. Handshakes are much more common.","A: Is it different when greeting elders?","B: Yes, we show more respect and might greet them with a slight bow of the head.","A: That sounds like a polite custom.","B: It really is part of our cultural heritage."],"questions":[{"prompt":"What do people in Mark's country normally do when meeting?","options":["A. Shake hands","B. Bow deeply","C. Wave only","D. Kiss both cheeks"],"answer":0,"explanation":"Nghe được: 'Yes, we normally shake hands...'"},{"prompt":"What might close friends do?","options":["A. Hug","B. Ignore each other","C. Argue","D. Bow"],"answer":0,"explanation":"Nghe được: '...and close friends might hug.'"},{"prompt":"Do they bow like people in Japan?","options":["A. No, they don't bow","B. Yes, all the time","C. Only in winter","D. Only at school"],"answer":0,"explanation":"Nghe được: 'No, we don't bow.'"},{"prompt":"How do they greet elders?","options":["A. Show more respect with a slight head bow","B. Shout loudly","C. Run away","D. Sit down immediately"],"answer":0,"explanation":"Nghe được: '...we show more respect and might greet them with a slight bow of the head.'"},{"prompt":"How does Mark feel about this custom?","options":["A. It is part of their cultural heritage","B. It is boring","C. It is too difficult","D. It should be stopped"],"answer":0,"explanation":"Nghe được: 'It really is part of our cultural heritage.'"}]},{"level":"hard","title":"Modern Impact on Traditional Lifestyles","intro":"Nghe bài nói chi tiết về tác động của thời hiện đại lên lối sống truyền thống.","script":"Modern lifestyles have brought significant changes to tribal communities around the world. While online learning and digital technology offer new opportunities for independent study, they also create a challenge for traditional habits. Many young people now prefer online interaction rather than offline communication with tribal elders. However, community leaders are working hard to revive ancient cultural practices. They organize workshops where skilled artisans teach younger generations how to make traditional crafts and build igloos. This revival ensures that unique cultural experiences will not disappear, creating a balanced lifestyle between the past and the future.","questions":[{"prompt":"What have modern lifestyles brought to tribal communities?","options":["A. Significant changes","B. Complete destruction","C. No impact at all","D. Financial crisis"],"answer":0,"explanation":"Nghe được: 'Modern lifestyles have brought significant changes to tribal communities...'"},{"prompt":"What challenge do digital technologies create?","options":["A. A challenge for traditional habits","B. Better weather conditions","C. More dogsleds","D. Faster nomadic movement"],"answer":0,"explanation":"Nghe được: '...they also create a challenge for traditional habits.'"},{"prompt":"What do many young people prefer nowadays?","options":["A. Online interaction","B. Writing letters","C. Living in tents","D. Hunting outdoors"],"answer":0,"explanation":"Nghe được: 'Many young people now prefer online interaction...'"},{"prompt":"What are community leaders working hard to do?","options":["A. Revive ancient cultural practices","B. Stop all technology","C. Leave their homeland","D. Build modern factories"],"answer":0,"explanation":"Nghe được: '...community leaders are working hard to revive ancient cultural practices.'"},{"prompt":"What is the ultimate goal of these workshops?","options":["A. Ensure unique cultural experiences do not disappear","B. Train professional waiters","C. Sell street food online","D. Learn foreign languages"],"answer":0,"explanation":"Nghe được: 'This revival ensures that unique cultural experiences will not disappear...'"}]}]},"unit7":{"unit":7,"title":"Environmental Protection","levels":[{"level":"easy","title":"Basic Environmental Actions","intro":"Nghe các câu ngắn và chọn đáp án đúng.","script":["We should plant more trees to protect our environment.","Plastic rubbish causes serious pollution in the ocean.","Remember to turn off lights when leaving the room.","Many endangered species live in coral reef habitats.","Using renewable sources helps reduce carbon footprint."],"questions":[{"prompt":"What should we do to protect our environment?","options":["A. Plant more trees","B. Cut down forests","C. Burn plastic","D. Waste water"],"answer":0,"explanation":"Nghe được: 'We should plant more trees to protect our environment.'"},{"prompt":"What causes serious pollution in the ocean?","options":["A. Fresh water","B. Plastic rubbish","C. Green grass","D. Clean sand"],"answer":1,"explanation":"Nghe được: 'Plastic rubbish causes serious pollution in the ocean.'"},{"prompt":"What should you do when leaving the room?","options":["A. Turn on the TV","B. Open the window","C. Turn off lights","D. Paint the wall"],"answer":2,"explanation":"Nghe được: 'Remember to turn off lights when leaving the room.'"},{"prompt":"Where do many endangered species live?","options":["A. Coral reef habitats","B. Busy cities","C. Dry deserts","D. Cold snow"],"answer":0,"explanation":"Nghe được: 'Many endangered species live in coral reef habitats.'"}]},{"level":"medium","title":"Protecting Marine Life","intro":"Nghe đoạn hội thoại về bảo vệ đời sống sinh vật biển.","script":["A: Have you read about marine pollution recently?","B: Yes, toxic substances are released into the sea every day.","A: That destroys the natural habitat of many sea creatures.","B: Exactly, dugongs and colorful coral are dying out.","A: Can we do anything to reduce this damage?","B: We can stop using single-use plastic products.","A: That is a practical way to participate in protection.","B: Every resident must act now before it is too late."],"questions":[{"prompt":"What is released into the sea every day according to B?","options":["A. Fresh oxygen","B. Toxic substances","C. Clean water","D. Renewable energy"],"answer":1,"explanation":"B nói: 'toxic substances are released into the sea every day.'"},{"prompt":"Which marine animals are mentioned as dying out?","options":["A. Sharks and whales","B. Dugongs and coral","C. Crabs and lobsters","D. Jellyfish and starfish"],"answer":1,"explanation":"B nói: 'dugongs and colorful coral are dying out.'"},{"prompt":"What practical way can people help reduce the damage?","options":["A. Stop using single-use plastic products","B. Buy more plastic bags","C. Release more carbon dioxide","D. Build more factories"],"answer":0,"explanation":"B đề xuất: 'We can stop using single-use plastic products.'"},{"prompt":"Who must act now to protect the environment?","options":["A. Only the government","B. Only foreign tourists","C. Every resident","D. Only factory owners"],"answer":2,"explanation":"B kết luận: 'Every resident must act now before it is too late.'"},{"prompt":"What is the general topic of the conversation?","options":["A. Marine pollution and protection","B. Camping in the forest","C. Cooking traditional food","D. Modern transportation"],"answer":0,"explanation":"Đoạn hội thoại bàn về ô nhiễm biển và cách bảo vệ sinh vật biển."}]},{"level":"hard","title":"Ecosystems and Climate Change","intro":"Nghe bài đọc chuyên sâu về hệ sinh thái và biến đổi khí hậu.","script":"Our planet's ecosystems are currently experiencing substantial challenges due to rapid industrial production and human negligence. Factories release massive quantities of carbon dioxide and toxic substances directly into the atmosphere and water systems. This relentless pollution accelerates global warming, threatening vulnerable habitats across the globe. Endangered species, from land animals to marine organisms like coral reefs, face the severe risk of extinction. To counter this crisis, governments and local residents must actively participate in conservation efforts, reduce carbon footprints, and shift towards renewable energy sources before irreversible damage occurs.","questions":[{"prompt":"What are causing substantial challenges to global ecosystems?","options":["A. Natural weather cycles","B. Rapid industrial production and human negligence","C. Animal migration patterns","D. Heavy rainfall and wind"],"answer":1,"explanation":"Bài nghe nêu: 'substantial challenges due to rapid industrial production and human negligence.'"},{"prompt":"Where do factories release carbon dioxide and toxic substances?","options":["A. Only into the soil","B. Into the atmosphere and water systems","C. Inside residential houses","D. Underneath coral reefs"],"answer":1,"explanation":"Bài nghe nêu: 'directly into the atmosphere and water systems.'"},{"prompt":"What is a direct consequence of relentless pollution?","options":["A. It accelerates global warming","B. It cleans up natural habitats","C. It increases oxygen production","D. It protects endangered species"],"answer":0,"explanation":"Bài nghe nêu: 'This relentless pollution accelerates global warming.'"},{"prompt":"Which organisms are specifically named as facing extinction risk?","options":["A. Farm animals","B. Marine organisms like coral reefs","C. Domestic pets","D. Zoo birds"],"answer":1,"explanation":"Bài nghe nêu: 'marine organisms like coral reefs, face the severe risk of extinction.'"},{"prompt":"What solution is suggested to counter this environmental crisis?","options":["A. Increase factory production","B. Shift towards renewable energy sources","C. Ignore carbon footprints","D. Stop all human residency"],"answer":1,"explanation":"Bài nghe đề xuất: 'shift towards renewable energy sources.'"}]}]},"unit9":{"unit":9,"title":"Natural Disasters","levels":[{"level":"easy","title":"Basic Listening Practice on Natural Disasters","intro":"Nghe các câu ngắn và chọn đáp án đúng nhất.","script":["A sudden earthquake shook the whole town yesterday morning.","The heavy rain caused a major flood in our area.","Rescue workers helped many victims after the storm.","People should prepare an emergency kit before a disaster.","Volcanic eruptions are extremely dangerous and destructive."],"questions":[{"prompt":"What shook the town yesterday morning?","options":["A. A sudden earthquake","B. A heavy storm","C. A big flood","D. A tornado"],"answer":0,"explanation":"Nghe được: 'A sudden earthquake shook the whole town yesterday morning.'"},{"prompt":"What did the heavy rain cause in the area?","options":["A. A volcanic eruption","B. A major flood","C. An earthquake","D. A landslide"],"answer":1,"explanation":"Nghe được: 'The heavy rain caused a major flood in our area.'"},{"prompt":"Who helped many victims after the storm?","options":["A. The local authority","B. Scientists","C. Rescue workers","D. Tourists"],"answer":2,"explanation":"Nghe được: 'Rescue workers helped many victims after the storm.'"},{"prompt":"What should people prepare before a disaster?","options":["A. A new bookcase","B. An emergency kit","C. Some poisonous plants","D. A map"],"answer":1,"explanation":"Nghe được: 'People should prepare an emergency kit before a disaster.'"},{"prompt":"How are volcanic eruptions described?","options":["A. Safe and quiet","B. Useful and pretty","C. Extremely dangerous and destructive","D. Predictable and easy"],"answer":2,"explanation":"Nghe được: 'Volcanic eruptions are extremely dangerous and destructive.'"}]},{"level":"medium","title":"Dialogue Listening on Weather and Disasters","intro":"Nghe đoạn hội thoại giữa hai học sinh và trả lời câu hỏi.","script":["Tom: Did you watch the weather forecast last night, Anna?","Anna: Yes, Tom. It said a tropical storm is coming.","Tom: Is it going to affect our region directly?","Anna: Yes, the authority warned that it will bring heavy rain and strong winds.","Tom: We should check our house and look out for falling branches.","Anna: Exactly. My dad already bought batteries and food for our emergency kit.","Tom: That is very smart. We must be well prepared.","Anna: I hope the storm will pass quickly without causing serious damage."],"questions":[{"prompt":"What is coming according to the weather forecast?","options":["A. An earthquake","B. A tropical storm","C. A volcanic eruption","D. A tsunami"],"answer":1,"explanation":"Nghe được: 'It said a tropical storm is coming.'"},{"prompt":"What did the authority warn about the storm?","options":["A. It will bring heavy rain and strong winds","B. It will cause an earthquake","C. It will bring snow and ice","D. It will happen next month"],"answer":0,"explanation":"Nghe được: 'the authority warned that it will bring heavy rain and strong winds.'"},{"prompt":"What did Tom suggest looking out for?","options":["A. Falling rocks","B. Falling branches","C. Broken glass","D. Wild animals"],"answer":1,"explanation":"Nghe được: 'look out for falling branches.'"},{"prompt":"What did Anna's dad buy for the emergency kit?","options":["A. Books and pens","B. Batteries and food","C. Clothes and shoes","D. Medicine and tents"],"answer":1,"explanation":"Nghe được: 'bought batteries and food for our emergency kit.'"},{"prompt":"What does Anna hope for at the end?","options":["A. The storm will bring rain for plants","B. They can go out to play","C. The storm will pass quickly without serious damage","D. School will be cancelled"],"answer":2,"explanation":"Nghe được: 'I hope the storm will pass quickly without causing serious damage.'"}]},{"level":"hard","title":"Advanced Talk on Natural Disasters and Prediction","intro":"Nghe bài nói chi tiết về công tác dự báo thảm họa thiên nhiên và trả lời câu hỏi.","script":"Natural disasters like earthquakes, tornadoes, and volcanic eruptions can cause immense destruction to property and human lives. In recent years, scientists have developed advanced technology to predict these disasters more accurately. For instance, volcanologists use specialized equipment to monitor pressure and liquid movement inside a volcano before it starts to erupt. Similarly, meteorologists track tropical storms using satellites and radar systems. When a severe weather warning is issued by the local authority, residents must follow safety instructions immediately. Having an emergency kit and knowing how to protect yourself during heavy shaking or strong winds can save your life. Although we cannot stop nature's fury, proper preparation and quick action significantly reduce the number of victims and overall damage.","questions":[{"prompt":"What do scientists try to do using advanced technology?","options":["A. Stop storms completely","B. Predict natural disasters more accurately","C. Create artificial earthquakes","D. Change weather patterns"],"answer":1,"explanation":"Nghe được: 'scientists have developed advanced technology to predict these disasters more accurately.'"},{"prompt":"What do volcanologists monitor inside a volcano?","options":["A. Temperature and wind speed","B. Pressure and liquid movement","C. Animal behavior","D. Rainfall and Fahrenheit"],"answer":1,"explanation":"Nghe được: 'monitor pressure and liquid movement inside a volcano.'"},{"prompt":"What do residents need to do when a warning is issued?","options":["A. Ignore the news and stay outside","B. Follow safety instructions immediately","C. Go closer to the volcano","D. Open all windows and doors"],"answer":1,"explanation":"Nghe được: 'residents must follow safety instructions immediately.'"},{"prompt":"Why is having an emergency kit important?","options":["A. It helps you save your life during disasters","B. It stops the tornado","C. It helps you predict earthquakes","D. It cleans up damaged property"],"answer":0,"explanation":"Nghe được: 'Having an emergency kit and knowing how to protect yourself... can save your life.'"},{"prompt":"What is the main message of the talk?","options":["A. Natural disasters can be completely prevented","B. Technology has made the world completely safe","C. Proper preparation and quick action reduce damage and victims","D. Earthquakes are the only dangerous disaster"],"answer":2,"explanation":"Nghe được: 'proper preparation and quick action significantly reduce the number of victims and overall damage.'"}]}]},"unit10":{"unit":10,"title":"Communication in the Future","levels":[{"level":"easy","title":"Future Communication Basics","intro":"Nghe các câu ngắn về giao tiếp trong tương lai và chọn đáp án đúng.","script":["People will use advanced smartphones for daily communication.","Language barriers will vanish with machine translation.","We will send voice messages instantly to friends.","Holography will change how we hold video conferences.","Telepathy allows people to share thoughts directly."],"questions":[{"prompt":"What kind of smartphones will people use?","options":["A. Advanced","B. Broken","C. Old","D. Heavy"],"answer":0,"explanation":"Audio: People will use advanced smartphones for daily communication."},{"prompt":"What will vanish with machine translation?","options":["A. Internet connection","B. Language barriers","C. Social networks","D. Tablets"],"answer":1,"explanation":"Audio: Language barriers will vanish with machine translation."},{"prompt":"How will people send voice messages?","options":["A. Slowly","B. Instantly","C. Rarely","D. Privately"],"answer":1,"explanation":"Audio: We will send voice messages instantly to friends."},{"prompt":"What technology will change video conferences?","options":["A. Holography","B. Carrier pigeons","C. Letters","D. Webcams"],"answer":0,"explanation":"Audio: Holography will change how we hold video conferences."}]},{"level":"medium","title":"Discussing Future Gadgets","intro":"Nghe đoạn hội thoại giữa hai học sinh về các thiết bị tương lai và trả lời câu hỏi.","script":["A: Hi Mark, have you heard about the new communication devices?","B: Yes, Mary. I read that we will use holography for meetings.","A: That sounds cool. Will it be difficult to use?","B: Not at all. It is a piece of cake to adjust.","A: What about internet connection speed?","B: It will be high-speed and run very smoothly.","A: That is wonderful for our privacy too.","B: Exactly, we can chat privately without any worry."],"questions":[{"prompt":"What will they use for meetings?","options":["A. Carrier pigeons","B. Holography","C. Letters","D. Voice messages"],"answer":1,"explanation":"Audio: I read that we will use holography for meetings."},{"prompt":"How does Mark describe using the new device?","options":["A. A piece of cake","B. Too complicated","C. Very dangerous","D. Quite boring"],"answer":0,"explanation":"Audio: It is a piece of cake to adjust."},{"prompt":"How will the internet connection be?","options":["A. Low-speed","B. Unstable","C. High-speed","D. Slow"],"answer":2,"explanation":"Audio: It will be high-speed and run very smoothly."},{"prompt":"What benefit is mentioned at the end?","options":["A. Privacy","B. High cost","C. Language barrier","D. Public sharing"],"answer":0,"explanation":"Audio: That is wonderful for our privacy too."},{"prompt":"How will the system run?","options":["A. Smoothly","B. Slowly","C. Badly","D. Loudly"],"answer":0,"explanation":"Audio: It will be high-speed and run very smoothly."}]},{"level":"hard","title":"The Evolution of Human Communication","intro":"Nghe bài nói chuyên sâu về sự tiến hóa của truyền thông nhân loại và chọn đáp án đúng.","script":"Communication has evolved remarkably from the days of carrier pigeons and handwritten letters to the modern era of social networks and smartphones. In the past, transmitting information took days or even weeks. Today, instant messaging, webcams, and high-speed internet connections allow people to interact live across continents. Looking toward the future, technological advancements will introduce even more astonishing tools. Experts believe that telepathy and advanced machine translation will completely eliminate language barriers. Furthermore, holography will make video conferences feel as if participants are in the same room. These changes will ensure that users can express their feelings more expressively while maintaining absolute privacy in their digital accounts.","questions":[{"prompt":"What is NOT mentioned as a past method of communication?","options":["A. Carrier pigeons","B. Handwritten letters","C. Social networks","D. Letters"],"answer":2,"explanation":"Audio: ...from the days of carrier pigeons and handwritten letters to the modern era of social networks..."},{"prompt":"What do instant messaging and webcams allow people to do?","options":["A. Interact live across continents","B. Send letters slowly","C. Train carrier pigeons","D. Avoid technology completely"],"answer":0,"explanation":"Audio: Today, instant messaging, webcams, and high-speed internet connections allow people to interact live across continents."},{"prompt":"What will completely eliminate language barriers in the future?","options":["A. Carrier pigeons and letters","B. Telepathy and advanced machine translation","C. Slow internet connections","D. Public social accounts"],"answer":1,"explanation":"Audio: Experts believe that telepathy and advanced machine translation will completely eliminate language barriers."},{"prompt":"What role will holography play in the future?","options":["A. Make video conferences feel like participants are in the same room","B. Slow down communication speed","C. Create language barriers","D. Replace smartphones with paper"],"answer":0,"explanation":"Audio: Furthermore, holography will make video conferences feel as if participants are in the same room."},{"prompt":"What will users be able to maintain while expressing their feelings?","options":["A. Public exposure","B. Absolute privacy in their digital accounts","C. High financial debts","D. Slow transmission"],"answer":1,"explanation":"Audio: These changes will ensure that users can express their feelings more expressively while maintaining absolute privacy in their digital accounts."}]}]},"unit11":{"unit":11,"title":"Science and Technology","levels":[{"level":"easy","title":"Listening Practice: Science and Technology in Daily Life","intro":"Nghe các câu ngắn về công nghệ và chọn đáp án đúng nhất.","script":["Students attend their online classes using digital applications.","The teacher asked us to be attentive during the lesson.","She wears contact lenses instead of traditional eyeglasses.","We need to buy a new computer screen for the office.","Scientists carry out important experiments in the laboratory."],"questions":[{"prompt":"What do students use to attend their online classes?","options":["A. Digital applications","B. Paper notebooks","C. Printed books","D. Blackboard"],"answer":0,"explanation":"Theo bài nghe: 'Students attend their online classes using digital applications.'"},{"prompt":"How did the teacher want students to be during the lesson?","options":["A. Noisy","B. Attentive","C. Sleepy","D. Absent"],"answer":1,"explanation":"Theo bài nghe: 'The teacher asked us to be attentive during the lesson.'"},{"prompt":"What does she wear instead of traditional eyeglasses?","options":["A. Sunglasses","B. Contact lenses","C. Safety glasses","D. Reading glasses"],"answer":1,"explanation":"Theo bài nghe: 'She wears contact lenses instead of traditional eyeglasses.'"},{"prompt":"What do they need to buy for the office?","options":["A. A new computer screen","B. A new smartphone","C. A fingerprint scanner","D. A robot teacher"],"answer":0,"explanation":"Theo bài nghe: 'We need to buy a new computer screen for the office.'"}]},{"level":"medium","title":"Listening Practice: A Conversation about Modern Inventions","intro":"Nghe đoạn hội thoại giữa hai học sinh về các phát minh mới và trả lời câu hỏi.","script":["A: Hi Tom, did you attend the science exhibition yesterday?","B: Yes, Mai. I saw many brilliant inventions there.","A: Really? What did you like the most?","B: I liked the robot bartender and the eye-tracking technology.","A: Are they convenient for everyday use?","B: Extremely convenient! Developers are working on them constantly.","A: That sounds amazing for our future digital world.","B: Exactly, technology is developing faster than ever!"],"questions":[{"prompt":"Where did Tom go yesterday?","options":["A. The art museum","B. The science exhibition","C. The sports center","D. The public library"],"answer":1,"explanation":"Theo bài nghe: 'did you attend the science exhibition yesterday?' - 'Yes, Mai.'"},{"prompt":"What did Tom like the most at the exhibition?","options":["A. Facial recognition and fingerprint scanner","B. Robot bartender and eye-tracking technology","C. Computer screens and contact lenses","D. Digital applications and breakout rooms"],"answer":1,"explanation":"Theo bài nghe: 'I liked the robot bartender and the eye-tracking technology.'"},{"prompt":"What did they say about the new technologies?","options":["A. They are difficult to use","B. They are too expensive","C. They are extremely convenient","D. They are dangerous"],"answer":2,"explanation":"Theo bài nghe: 'Extremely convenient!'"},{"prompt":"Who is constantly working on these inventions?","options":["A. Developers","B. Students","C. Bartenders","D. Teachers"],"answer":0,"explanation":"Theo bài nghe: 'Developers are working on them constantly.'"},{"prompt":"How is technology developing according to Tom?","options":["A. Slower than before","B. Faster than ever","C. Very slowly","D. Not changing at all"],"answer":1,"explanation":"Theo bài nghe: 'technology is developing faster than ever!'"}]},{"level":"hard","title":"Listening Practice: The Evolution of Scientific Discoveries","intro":"Nghe đoạn văn dài nói về sự phát triển của các phát minh khoa học và trả lời câu hỏi.","script":"Throughout human history, brilliant inventors and scientists have changed the world through their remarkable discoveries. In the past, communicating over long distances was slow and difficult. Today, thanks to digital technology, people across the planet can communicate instantly using advanced applications and breakout rooms in online meetings. Furthermore, modern security systems now rely heavily on facial recognition and fingerprint scanners instead of traditional keys. Scientists continue to carry out complex experiments in developing nations, pushing the boundaries of human knowledge and creativity. As students, we must study hard and embrace these wonderful technological advancements to build a better future for everyone.","questions":[{"prompt":"What did brilliant inventors and scientists do throughout human history?","options":["A. Changed the world through remarkable discoveries","B. Made communication slower and more difficult","C. Stopped doing scientific experiments","D. Created traditional keys for doors"],"answer":0,"explanation":"Theo bài nghe: 'brilliant inventors and scientists have changed the world through their remarkable discoveries.'"},{"prompt":"How can people across the planet communicate today?","options":["A. Only through traditional letters","B. Instantly using advanced applications and breakout rooms","C. By using facial recognition","D. With fingerprint scanners"],"answer":1,"explanation":"Theo bài nghe: 'people across the planet can communicate instantly using advanced applications and breakout rooms in online meetings.'"},{"prompt":"What do modern security systems rely heavily on now?","options":["A. Traditional keys","B. Paper documents","C. Facial recognition and fingerprint scanners","D. Computer screens and contact lenses"],"answer":2,"explanation":"Theo bài nghe: 'modern security systems now rely heavily on facial recognition and fingerprint scanners instead of traditional keys.'"},{"prompt":"What do scientists continue to carry out in developing nations?","options":["A. Complex experiments","B. Online meetings","C. Language classes","D. Sports competitions"],"answer":0,"explanation":"Theo bài nghe: 'Scientists continue to carry out complex experiments in developing nations.'"},{"prompt":"What does the speaker advise students to do?","options":["A. Ignore technological advancements","B. Study hard and embrace technological advancements","C. Stop using digital applications","D. Avoid scientific research"],"answer":1,"explanation":"Theo bài nghe: 'As students, we must study hard and embrace these wonderful technological advancements to build a better future for everyone.'"}]}]},"unit12":{"unit":12,"title":"Life on Other Planets","levels":[{"level":"easy","title":"Listening Practice: Planets and Space","intro":"Nghe đoạn băng ngắn và chọn đáp án đúng nhất.","script":["Astronauts travel into space using a huge rocket.","Mars is known as the red planet in our solar system.","We look at distant stars with a large telescope.","Some people enjoy reading science fiction books.","An alien creature might live on another planet."],"questions":[{"prompt":"What do astronauts use to travel into space?","options":["A. A rocket","B. A telescope","C. A bicycle","D. A train"],"answer":0,"explanation":"Theo đoạn nghe: Astronauts travel into space using a huge rocket."},{"prompt":"Which planet is known as the red planet?","options":["A. Venus","B. Mars","C. Saturn","D. Jupiter"],"answer":1,"explanation":"Theo đoạn nghe: Mars is known as the red planet in our solar system."},{"prompt":"What do we use to look at distant stars?","options":["A. A camera","B. Glasses","C. A telescope","D. A mirror"],"answer":2,"explanation":"Theo đoạn nghe: We look at distant stars with a large telescope."},{"prompt":"What kind of books do some people enjoy reading?","options":["A. Science fiction books","B. Cook books","C. History books","D. Art books"],"answer":0,"explanation":"Theo đoạn nghe: Some people enjoy reading science fiction books."}]},{"level":"medium","title":"Listening Practice: A Conversation on Space","intro":"Nghe đoạn hội thoại và chọn đáp án chính xác.","script":["A: Have you ever watched a thrilling movie about aliens?","B: Yes, I watched a great thriller last night.","A: Did the spaceship break down in the story?","B: Yes, and the commander had to repair it quickly.","A: Were there any strange creatures attacking them?","B: Exactly, strange creatures tried to take over the ship.","A: Did the crew oppose the attack successfully?","B: Yes, they fought back and won the battle."],"questions":[{"prompt":"What kind of movie did B watch last night?","options":["A. A comedy","B. A thrilling movie about aliens","C. A romantic film","D. A documentary"],"answer":1,"explanation":"Theo đoạn hội thoại: Have you ever watched a thrilling movie about aliens? - Yes, I watched a great thriller last night."},{"prompt":"What happened to the spaceship in the story?","options":["A. It broke down","B. It landed on Mars","C. It disappeared","D. It burned up"],"answer":0,"explanation":"Theo đoạn hội thoại: Did the spaceship break down in the story?"},{"prompt":"Who had to repair the spaceship quickly?","options":["A. The professor","B. The alien","C. The commander","D. The player"],"answer":2,"explanation":"Theo đoạn hội thoại: Yes, and the commander had to repair it quickly."},{"prompt":"What did the strange creatures try to do?","options":["A. Clean the ship","B. Take over the ship","C. Paint the ship","D. Fix the ship"],"answer":1,"explanation":"Theo đoạn hội thoại: strange creatures tried to take over the ship."},{"prompt":"Did the crew oppose the attack successfully?","options":["A. Yes, they fought back and won.","B. No, they lost immediately.","C. They ran away.","D. They surrendered."],"answer":0,"explanation":"Theo đoạn hội thoại: Yes, they fought back and won the battle."}]},{"level":"hard","title":"Listening Practice: The Possibility of Life on Mars","intro":"Nghe đoạn bài giảng dài và trả lời các câu hỏi.","script":"Many scientists around the world often think about the possibility of finding life on Mars and other planets in our solar system. When we look through powerful telescopes, we can see deep craters on the rocky surface of the red planet. Some researchers doubt that intelligent aliens exist, while others believe it is possible under certain extreme conditions. If a spaceship ever lands on Mars, astronauts might discover strange new creatures hiding beneath the surface. However, we must be very careful because any unknown alien life form could potentially attack or try to take over our exploring teams.","questions":[{"prompt":"What do scientists often think about?","options":["A. Building new rockets","B. The possibility of finding life on Mars and other planets","C. Studying the moon craters only","D. Fixing broken spaceships"],"answer":1,"explanation":"Theo đoạn nghe: Many scientists around the world often think about the possibility of finding life on Mars and other planets in our solar system."},{"prompt":"What can we see on the rocky surface of Mars through telescopes?","options":["A. Deep craters","B. Tall buildings","C. Green forests","D. Blue oceans"],"answer":0,"explanation":"Theo đoạn nghe: we can see deep craters on the rocky surface of the red planet."},{"prompt":"What do some researchers feel about intelligent aliens?","options":["A. They are certain they exist","B. They doubt they exist","C. They talk to them daily","D. They invited them"],"answer":1,"explanation":"Theo đoạn nghe: Some researchers doubt that intelligent aliens exist..."},{"prompt":"What might astronauts discover if a spaceship lands on Mars?","options":["A. Strange new creatures hiding beneath the surface","B. Modern cities","C. Advanced computers","D. Delicious food"],"answer":0,"explanation":"Theo đoạn nghe: astronauts might discover strange new creatures hiding beneath the surface."},{"prompt":"Why must astronauts be very careful according to the speaker?","options":["A. Because of heavy rain","B. Because unknown alien life forms could potentially attack","C. Because their spacesuit might tear","D. Because they have no fuel"],"answer":1,"explanation":"Theo đoạn nghe: because any unknown alien life form could potentially attack or try to take over our exploring teams."}]}]}};
